namespace studio {
namespace {
using Object=json::jobject;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(std::string("Weights: ")+message);}
std::string quoted(const std::string& s){return json::parsing::encode_string(s.c_str());}
std::ostringstream stream(){std::ostringstream s;s.imbue(std::locale::classic());s<<std::setprecision(17);return s;}
std::string read(const std::filesystem::path& path){std::ifstream f(path,std::ios::binary|std::ios::ate);require(bool(f),"cannot open file");auto n=f.tellg();require(n>=0&&uint64_t(n)<=64*1024*1024,"file exceeds 64 MiB");std::string b(size_t(n),'\0');f.seekg(0);f.read(b.data(),n);require(bool(f),"read failed");if(b.compare(0,3,"\xef\xbb\xbf")==0)b.erase(0,3);return b;}
double number(const Object& o,const char* key){require(o[key].is_number(),"expected numeric field");auto in=std::istringstream(o.get(key));in.imbue(std::locale::classic());double v;in>>v;require(bool(in)&&std::isfinite(v)&&(in>>std::ws,in.eof()),"invalid number");return v;}
std::string string(const Object& o,const char* key){require(o[key].is_string(),"expected string field");return o[key].as_string();}
uint64_t integer(const std::string& s){require(!s.empty()&&s.find_first_not_of("0123456789")==s.npos,"invalid integer");size_t n=0;auto v=std::stoull(s,&n);require(n==s.size(),"invalid integer");return v;}
void read_values(WeightSnapshot& s,const Object& root,const char* key){auto array=Object::parse(root.get(key));require(array.is_array()&&array.size()==s.config.synapses.size(),"weight count does not match companion topology");s.weights.reserve(array.size());for(size_t i=0;i<array.size();++i){Object value;value.set("v",array.get(i));s.weights.push_back(number(value,"v"));}}
std::string node_key(const Neuron& n){return quoted(n.name)+":"+std::to_string(int(n.model))+":"+std::to_string(n.inhibitory);}
std::vector<std::string> topology(const Config& c){std::vector<std::string> result;for(const auto& n:c.neurons)result.push_back("N:"+node_key(n));for(const auto& a:c.astrocytes)result.push_back("A:"+quoted(a.name));for(const auto& g:c.gaps){auto a=quoted(c.astrocytes[g.a].name),b=quoted(c.astrocytes[g.b].name);if(a>b)std::swap(a,b);result.push_back("G:"+a+":"+b);}std::sort(result.begin(),result.end());return result;}
bool selected(const Synapse& e,const WeightSettings& s){const bool inhibitory=inhibitory_analysis_edge(e);return (!s.polarity||(s.polarity==2)==inhibitory)&&(!s.model||int(e.model)==s.model-1)&&(!s.enabled||(s.enabled==1)==e.enabled);}
double value(double w,const WeightSettings& s){return s.absolute?std::abs(w):w;}
void add(double x,double& sum,double& correction){const double y=x-correction,t=sum+y;correction=(t-sum)-y;sum=t;}
WeightStatistics stats(std::vector<double> values){WeightStatistics s;s.count=values.size();if(values.empty())return s;std::sort(values.begin(),values.end());s.minimum=values.front();s.maximum=values.back();size_t m=values.size()/2;s.median=values.size()%2?values[m]:values[m-1]+(values[m]-values[m-1])/2;double correction=0;for(double v:values)add(v,s.sum,correction);if(s.minimum==s.maximum){s.mean=s.minimum;return s;}s.mean=s.sum/values.size();double variance=0;correction=0;for(double v:values)add((v-s.mean)*(v-s.mean),variance,correction);s.stddev=std::sqrt(variance/values.size());return s;}
std::vector<double> edges(const std::vector<double>& values,int bins){
    double lo=0,hi=1;
    if(!values.empty()){
        auto r=std::minmax_element(values.begin(),values.end());lo=*r.first;hi=*r.second;
        // Adjacent representable weights cannot be split into many distinct edges.
        // Expand the display range only; all statistics and deltas keep raw values.
        const double resolution=2*std::numeric_limits<double>::epsilon()*std::max({1.,std::abs(lo),std::abs(hi)});
        if((hi-lo)/bins<=resolution){double pad=std::max(.5,std::abs(lo)*.05);lo-=pad;hi+=pad;}
    }
    std::vector<double> out;for(int i=0;i<=bins;++i)out.push_back(i==bins?hi:lo+(hi-lo)*i/bins);return out;
}
std::vector<double> histogram(const std::vector<double>& values,const std::vector<double>& bins){std::vector<double> counts(bins.size()-1,0);for(double v:values){auto i=std::upper_bound(bins.begin(),bins.end(),v)-bins.begin();size_t k=std::min(counts.size()-1,size_t(std::max<std::ptrdiff_t>(1,i)-1));++counts[k];}return counts;}
void stats_json(std::ostream& o,const WeightStatistics& s){o<<"{\"count\":"<<s.count;if(s.count)o<<",\"mean\":"<<s.mean<<",\"median\":"<<s.median<<",\"stddev_population\":"<<s.stddev<<",\"min\":"<<s.minimum<<",\"max\":"<<s.maximum<<",\"sum\":"<<s.sum;else o<<",\"mean\":null,\"median\":null,\"stddev_population\":null,\"min\":null,\"max\":null,\"sum\":0";o<<",\"learning_count\":"<<s.learning_count<<",\"at_lower\":"<<s.at_lower<<",\"at_upper\":"<<s.at_upper<<",\"fraction_lower\":";if(s.learning_count)o<<double(s.at_lower)/s.learning_count;else o<<"null";o<<",\"fraction_upper\":";if(s.learning_count)o<<double(s.at_upper)/s.learning_count;else o<<"null";o<<"}";}
std::string csv(const std::string& s){std::string out="\"";for(char c:s){out+=c;if(c=='"')out+='"';}return out+'"';}
}
bool inhibitory_analysis_edge(const Synapse& e){return e.model==SynapseModel::ConductanceSTP?e.reversal<=-40:(!e.stdp&&e.weight<0);}
void validate_weights(const WeightSnapshot& s){auto problem=validate(s.config);if(!problem.empty())throw std::runtime_error(problem);require(s.weights.size()==s.config.synapses.size()&&s.weights.size()<=MaxSynapses,"invalid weights dimension");require(std::isfinite(s.time)&&s.time>=0&&s.time<=s.config.duration,"invalid snapshot time");require(!s.name.empty()&&s.name.size()<=512&&s.origin.size()<=8192&&s.name.find('\0')==s.name.npos&&s.origin.find('\0')==s.origin.npos,"invalid snapshot metadata");for(size_t i=0;i<s.weights.size();++i){double w=s.weights[i];const auto& e=s.config.synapses[i];require(std::isfinite(w)&&std::abs(w)<=10,"invalid weight");if(e.model==SynapseModel::ConductanceSTP)require(w>=0,"negative conductance weight");if(e.stdp)require(w>=e.weight_min&&w<=e.weight_max,"learned weight outside configured bounds");}}
WeightSnapshot capture_weights(const Config& c,const std::vector<StdpState>& p,double time,uint64_t steps,const std::string& name){WeightSnapshot s;s.config=c;s.time=time;s.steps=steps;s.name=name;s.origin="Completed Simulator step / SimulationRunner";for(const auto& w:p)s.weights.push_back(w.weight);validate_weights(s);return s;}
WeightSnapshot initial_weights(const Config& c,const std::string& name){WeightSnapshot s;s.config=c;s.name=name;s.origin="Initial Config weights; not reconstructed historical data";for(const auto& e:c.synapses)s.weights.push_back(e.weight);validate_weights(s);return s;}
std::vector<std::string> weight_edge_ids(const Config& c,std::string& error){std::set<std::string> nodes,astro,ids;for(const auto& n:c.neurons)if(!nodes.insert(n.name).second)error="Неоднозначная идентичность: повторяются имена нейронов.";for(const auto& a:c.astrocytes)if(!astro.insert(a.name).second)error="Неоднозначная идентичность: повторяются имена астроцитов.";std::vector<std::string> result;for(const auto& e:c.synapses){auto id=node_key(c.neurons[e.source])+" -> "+node_key(c.neurons[e.target])+" / "+std::to_string(int(e.model))+" / "+(e.astro<0?"none":quoted(c.astrocytes[e.astro].name));if(!ids.insert(id).second)error="Неоднозначная идентичность параллельных связей: попарное сравнение запрещено.";result.push_back(std::move(id));}return result;}
std::string compatible_weights(const WeightSnapshot& a,const WeightSnapshot& b){std::string error;auto x=weight_edge_ids(a.config,error),y=weight_edge_ids(b.config,error);if(!error.empty())return error;std::sort(x.begin(),x.end());std::sort(y.begin(),y.end());if(x!=y||topology(a.config)!=topology(b.config))return "Несовместимая топология или идентичность узлов/связей. Разность по индексам запрещена.";return {};}
WeightAnalysis analyze_weights(const std::vector<const WeightSnapshot*>& snapshots,const WeightSettings& s,size_t reference,size_t target){require(!snapshots.empty()&&snapshots.size()<=17,"select 1..17 snapshots");require(s.polarity>=0&&s.polarity<=2&&s.model>=0&&s.model<=3&&s.enabled>=0&&s.enabled<=2&&s.bins>=1&&s.bins<=512&&std::isfinite(s.boundary_tolerance)&&s.boundary_tolerance>=0&&s.boundary_tolerance<=100,"invalid analysis settings");require(reference<snapshots.size()&&target<snapshots.size(),"invalid comparison selection");WeightAnalysis out;out.reference=reference;out.target=target;std::vector<double> all;
    for(auto snap:snapshots){validate_weights(*snap);WeightDistribution d;for(size_t i=0;i<snap->weights.size();++i)if(selected(snap->config.synapses[i],s)){d.indices.push_back(i);d.values.push_back(value(snap->weights[i],s));}d.stats=stats(d.values);for(auto i:d.indices){const auto& e=snap->config.synapses[i];if(e.stdp){++d.stats.learning_count;d.stats.at_lower+=std::abs(snap->weights[i]-e.weight_min)<=s.boundary_tolerance;d.stats.at_upper+=std::abs(snap->weights[i]-e.weight_max)<=s.boundary_tolerance;}}all.insert(all.end(),d.values.begin(),d.values.end());out.distributions.push_back(std::move(d));}
    out.edges=edges(all,s.bins);for(auto& d:out.distributions)d.counts=histogram(d.values,out.edges);
    const auto& a=*snapshots[reference];const auto& b=*snapshots[target];auto& delta=out.difference;delta.error=compatible_weights(a,b);if(!delta.error.empty())return out;std::string ignored;auto ids=weight_edge_ids(a.config,ignored),other=weight_edge_ids(b.config,ignored);std::map<std::string,size_t> lookup;for(size_t j=0;j<other.size();++j)lookup.emplace(other[j],j);std::vector<double> changes;
    for(size_t i=0;i<ids.size();++i){size_t j=lookup.at(ids[i]);if(!selected(a.config.synapses[i],s)||!selected(b.config.synapses[j],s))continue;double raw=b.weights[j]-a.weights[i],d=value(b.weights[j],s)-value(a.weights[i],s);delta.changes.push_back({i,j,raw,d,ids[i]});changes.push_back(d);delta.unchanged+=raw==0;}
    delta.stats=stats(changes);delta.edges=edges(changes,s.bins);delta.counts=histogram(changes,delta.edges);std::sort(delta.changes.begin(),delta.changes.end(),[](const auto& a,const auto& b){return std::abs(a.delta)!=std::abs(b.delta)?std::abs(a.delta)>std::abs(b.delta):a.id<b.id;});return out;
}
void save_weights(const WeightSnapshot& s,const std::filesystem::path& path){validate_weights(s);auto out=stream();out<<"{\"document_type\":\"network_studio_weight_snapshot\",\"schema_version\":1,\"identity\":\"named-endpoints-model-astro-v1\",\"name\":"<<quoted(s.name)<<",\"origin\":"<<quoted(s.origin)<<",\"time_s\":"<<s.time<<",\"steps\":"<<quoted(std::to_string(s.steps))<<",\"config\":"<<serialize(s.config)<<",\"weights\":[";for(size_t i=0;i<s.weights.size();++i){if(i)out<<",";out<<s.weights[i];}out<<"]}\n";auto bytes=out.str();require(bytes.size()<=64*1024*1024,"snapshot exceeds 64 MiB");write_atomic(path,bytes);}
WeightSnapshot load_weights(const std::filesystem::path& path){const auto o=Object::parse(read(path));require(string(o,"document_type")=="network_studio_weight_snapshot"&&number(o,"schema_version")==1&&string(o,"identity")=="named-endpoints-model-astro-v1","unsupported weight snapshot");WeightSnapshot s;s.name=string(o,"name");s.origin=string(o,"origin");s.time=number(o,"time_s");s.steps=integer(string(o,"steps"));s.config=deserialize(o.get("config"));read_values(s,o,"weights");validate_weights(s);return s;}
WeightSnapshot load_weight_summary(const std::filesystem::path& path){auto name=path.filename().u8string();const std::string suffix="_summary.json";require(name.size()>suffix.size()&&name.compare(name.size()-suffix.size(),suffix.size(),suffix)==0,"choose PREFIX_summary.json with its same-prefix experiment sidecar");auto config_path=path.parent_path()/std::filesystem::u8path(name.substr(0,name.size()-suffix.size())+"_experiment.json");const auto o=Object::parse(read(path));WeightSnapshot s;s.config=load_config(config_path);s.time=number(o,"time_s");s.steps=integer(o.get("steps"));s.name=path.stem().u8string();s.origin="Legacy same-prefix summary + experiment; no embedded provenance hash: "+path.u8string();require(o["error"].is_string()&&string(o,"error").empty(),"summary reports a calculation error");read_values(s,o,"final_synapse_weights");validate_weights(s);return s;}
void export_weights(const std::vector<const WeightSnapshot*>& snapshots,const WeightSettings& settings,size_t reference,size_t target,const std::filesystem::path& prefix){auto result=analyze_weights(snapshots,settings,reference,target);auto raw=stream(),hist=stream(),changes=stream(),meta=stream();raw<<"snapshot,time_s,row_0based,stable_id,source,target,inhibitory,model,enabled,stdp,weight_min,weight_max,selected,raw_weight,display_value\n";hist<<"snapshot,bin,left,right,count\n";
    meta<<"{\"document_type\":\"network_studio_weight_analysis\",\"schema_version\":1,\"representation\":"<<quoted(settings.absolute?"absolute":"signed")<<",\"polarity\":"<<settings.polarity<<",\"model\":"<<settings.model<<",\"enabled\":"<<settings.enabled<<",\"bins\":"<<settings.bins<<",\"boundary_tolerance\":"<<settings.boundary_tolerance<<",\"stddev_ddof\":0,\"boundary_denominator\":\"selected STDP-configured edges\",\"snapshots\":[";
    for(size_t k=0;k<snapshots.size();++k){const auto& s=*snapshots[k];std::string identity_error;auto ids=weight_edge_ids(s.config,identity_error);if(k)meta<<",";meta<<"{\"name\":"<<quoted(s.name)<<",\"time_s\":"<<s.time<<",\"origin\":"<<quoted(s.origin)<<",\"identity_warning\":"<<quoted(identity_error)<<",\"statistics\":";stats_json(meta,result.distributions[k].stats);meta<<"}";
        for(size_t i=0;i<s.weights.size();++i){const auto& e=s.config.synapses[i];raw<<k<<","<<s.time<<","<<i<<","<<csv(ids[i])<<","<<csv(s.config.neurons[e.source].name)<<","<<csv(s.config.neurons[e.target].name)<<","<<inhibitory_analysis_edge(e)<<","<<int(e.model)<<","<<e.enabled<<","<<e.stdp<<","<<e.weight_min<<","<<e.weight_max<<","<<selected(e,settings)<<","<<s.weights[i]<<","<<value(s.weights[i],settings)<<"\n";}
        for(size_t i=0;i+1<result.edges.size();++i)hist<<k<<","<<i<<","<<result.edges[i]<<","<<result.edges[i+1]<<","<<result.distributions[k].counts[i]<<"\n";
    }
    const auto& d=result.difference;meta<<"],\"difference\":{\"reference\":"<<reference<<",\"target\":"<<target<<",\"error\":"<<quoted(d.error)<<",\"pair_filter\":\"intersection: both endpoints pass filters\",\"exactly_unchanged_raw\":"<<d.unchanged<<",\"statistics\":";stats_json(meta,d.stats);meta<<"}}\n";
    changes<<"rank,stable_id,before_index,after_index,before_raw,after_raw,raw_delta,display_delta\n";for(size_t i=0;i<d.changes.size();++i){const auto& x=d.changes[i];changes<<i+1<<","<<csv(x.id)<<","<<x.before<<","<<x.after<<","<<snapshots[reference]->weights[x.before]<<","<<snapshots[target]->weights[x.after]<<","<<x.raw_delta<<","<<x.delta<<"\n";}
    auto delta_hist=stream();delta_hist<<"bin,left,right,count\n";for(size_t i=0;i<d.counts.size();++i)delta_hist<<i<<","<<d.edges[i]<<","<<d.edges[i+1]<<","<<d.counts[i]<<"\n";
    auto save=[&](const char* suffix,const std::string& bytes){auto p=prefix;p+=suffix;write_atomic(p,bytes);};save("_weights.csv",raw.str());save("_histograms.csv",hist.str());save("_changes.csv",changes.str());save("_delta_histogram.csv",delta_hist.str());save("_statistics.json",meta.str());
}
}
